const cx = W()/2, cy = H()/2;
const minDim = Math.min(W(), H());
const colors = (PALETTE && PALETTE.length>=3) ? PALETTE : ['#7c1f3a','#e0a13d','#fdf0e4'];
const gx = W()*0.82, gy = H()*0.18;

const N = 130;
const particles = [];
for (let i=0;i<N;i++){
  particles.push({
    baseAngle: Math.random()*Math.PI*2,
    ringR: minDim*(0.30+Math.random()*0.16),
    speed: (Math.random()*0.15+0.05) * (Math.random()<0.5?1:-1),
    wobble: Math.random()*Math.PI*2,
    wobbleSpeed: 0.3+Math.random()*0.5,
    size: 1.2+Math.random()*2.4,
    colorIdx: Math.floor(Math.random()*3),
    trail: []
  });
}

const streams = [];
for (let s=0;s<6;s++){
  streams.push({ t: Math.random(), speed: 0.0025+Math.random()*0.002, targetAngle: Math.random()*Math.PI*2, size: 2.5+Math.random()*1.8 });
}

function hexToRgba(hex, a){
  const h = hex.replace('#','');
  const r = parseInt(h.substring(0,2),16);
  const g = parseInt(h.substring(2,4),16);
  const b = parseInt(h.substring(4,6),16);
  return 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')';
}

function drawPomegranate(time){
  ctx.save();
  ctx.translate(gx, gy);
  const pulse = 1 + Math.sin(time*0.0009)*0.04;
  ctx.scale(pulse, pulse);
  const r = minDim*0.085;

  const grad = ctx.createRadialGradient(0,0, r*0.2, 0,0, r*2.2);
  grad.addColorStop(0, hexToRgba(colors[0], 0.55));
  grad.addColorStop(0.5, hexToRgba(colors[0], 0.18));
  grad.addColorStop(1, hexToRgba(colors[0], 0));
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(0,0,r*2.2,0,Math.PI*2);
  ctx.fill();

  const bodyGrad = ctx.createRadialGradient(-r*0.3,-r*0.3, r*0.1, 0,0, r);
  bodyGrad.addColorStop(0, hexToRgba(colors[1], 0.95));
  bodyGrad.addColorStop(0.6, hexToRgba(colors[0], 0.9));
  bodyGrad.addColorStop(1, hexToRgba(colors[0], 0.75));
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.ellipse(0,0, r, r*0.92, 0, 0, Math.PI*2);
  ctx.fill();

  ctx.strokeStyle = hexToRgba(colors[1], 0.85);
  ctx.lineWidth = r*0.06;
  for (let i=0;i<6;i++){
    const a = -Math.PI/2 + (i-2.5)*0.22;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a)*r*0.5, Math.sin(a)*r*0.95 - r*0.05);
    ctx.lineTo(Math.cos(a)*r*0.75, Math.sin(a)*r*1.3 - r*0.1);
    ctx.stroke();
  }

  ctx.strokeStyle = hexToRgba(colors[2], 0.5);
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-r*0.5, -r*0.2);
  ctx.quadraticCurveTo(0, r*0.15, r*0.55, -r*0.35);
  ctx.stroke();

  for (let i=0;i<10;i++){
    const ang = (i/10)*Math.PI*2;
    const rad = r*0.35*Math.random()+r*0.15;
    ctx.beginPath();
    ctx.fillStyle = hexToRgba(colors[2], 0.85);
    ctx.arc(Math.cos(ang)*rad, Math.sin(ang)*rad*0.7, 2.2, 0, Math.PI*2);
    ctx.fill();
  }

  ctx.restore();
}

function draw(now){
  const time = now;
  const w = W(), h = H();
  ctx.clearRect(0,0,w,h);

  ctx.lineWidth = 0.6;
  for (let i=0;i<particles.length;i++){
    const p = particles[i];
    const a = p.baseAngle + time*0.00004*p.speed*10;
    const wob = Math.sin(time*0.0006*p.wobbleSpeed + p.wobble)*minDim*0.015;
    const r = p.ringR + wob;
    p.x = cx + Math.cos(a)*r;
    p.y = cy + Math.sin(a)*r*0.82;
  }
  for (let i=0;i<particles.length;i++){
    const p = particles[i];
    for (let j=i+1;j<particles.length;j++){
      const q = particles[j];
      const dx = p.x-q.x, dy = p.y-q.y;
      const d2 = dx*dx+dy*dy;
      const lim = minDim*0.055;
      if (d2 < lim*lim){
        const dist = Math.sqrt(d2);
        const alpha = (1 - dist/lim) * 0.18;
        ctx.strokeStyle = hexToRgba(colors[1], alpha);
        ctx.beginPath();
        ctx.moveTo(p.x,p.y);
        ctx.lineTo(q.x,q.y);
        ctx.stroke();
      }
    }
  }

  for (let i=0;i<particles.length;i++){
    const p = particles[i];
    p.trail.push({x:p.x, y:p.y});
    if (p.trail.length>7) p.trail.shift();

    for (let k=0;k<p.trail.length;k++){
      const pt = p.trail[k];
      const alpha = (k/p.trail.length) * 0.35;
      ctx.beginPath();
      ctx.fillStyle = hexToRgba(colors[p.colorIdx], alpha);
      ctx.arc(pt.x, pt.y, p.size*0.6, 0, Math.PI*2);
      ctx.fill();
    }

    ctx.save();
    ctx.shadowColor = hexToRgba(colors[p.colorIdx], 0.9);
    ctx.shadowBlur = 6;
    ctx.beginPath();
    ctx.fillStyle = hexToRgba(colors[p.colorIdx], 0.95);
    ctx.arc(p.x, p.y, p.size, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
  }

  for (const s of streams){
    s.t += s.speed;
    if (s.t>1){ s.t=0; s.targetAngle = Math.random()*Math.PI*2; }
    const targetR = minDim*0.38;
    const tx = cx + Math.cos(s.targetAngle)*targetR;
    const ty = cy + Math.sin(s.targetAngle)*targetR*0.82;
    const midx = (gx+tx)/2 + Math.sin(s.t*Math.PI)*minDim*0.06;
    const midy = (gy+ty)/2 - Math.cos(s.t*Math.PI)*minDim*0.06;
    const et = s.t;
    const x = (1-et)*(1-et)*gx + 2*(1-et)*et*midx + et*et*tx;
    const y = (1-et)*(1-et)*gy + 2*(1-et)*et*midy + et*et*ty;
    const alpha = Math.sin(et*Math.PI);
    ctx.save();
    ctx.shadowColor = hexToRgba(colors[1], 0.9);
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.fillStyle = hexToRgba(colors[1], 0.6+alpha*0.4);
    ctx.arc(x, y, s.size, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
  }

  drawPomegranate(time);

  requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
